import{_ as s,o as a,c as t,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Process scheduling","description":"","frontmatter":{},"headers":[],"relativePath":"arch/scheduler.md","filePath":"arch/scheduler.md"}'),c={name:"arch/scheduler.md"};function r(d,e,i,n,h,l){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="process-scheduling" tabindex="-1">Process scheduling <a class="header-anchor" href="#process-scheduling" aria-label="Permalink to &quot;Process scheduling&quot;">​</a></h1><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p><code>kernel/core/core_sched.{c,h}</code>: preemptive, priority-based with time-slice round-robin inside a priority level. Task control blocks carry state, priority, slices, and the saved frame; the context switch (<code>arch/x86_64/arch_context_switch.S</code>) is ABI-probe-verified (SysV 16-byte stack alignment at the dispatch call - BUG-0137).</p><h2 id="ticks" tabindex="-1">Ticks <a class="header-anchor" href="#ticks" aria-label="Permalink to &quot;Ticks&quot;">​</a></h2><p>The PIT fires IRQ0 at 100 Hz: tick counter, <code>g_boot_time_ms</code>, the soft-timer wheel, and the scheduler&#39;s preemption all hang off it. <code>sched</code>, <code>ps</code>, <code>nice</code>, <code>sleep</code>, <code>kill</code>, <code>spawn</code>, <code>multi</code> are the user-facing commands.</p><h2 id="background-tasks-and-the-policy-watchdog" tabindex="-1">Background tasks and the policy watchdog <a class="header-anchor" href="#background-tasks-and-the-policy-watchdog" aria-label="Permalink to &quot;Background tasks and the policy watchdog&quot;">​</a></h2><p>Long-running work (<code>g6_test &amp;</code>, spinners) runs as background tasks. The watchdog subsystem (<code>kernel/core/core_watchdog.c</code>) adds monitored slots: a task that must feed its slot and stops doing so is killed - with the reason logged - while the kernel itself stays alive. The hardware watchdogs (TCO/WDAT) protect the whole machine instead: see <a href="./../internals/watchdog.html">internals/watchdog.md</a>.</p><h2 id="signals-and-processes" tabindex="-1">Signals and processes <a class="header-anchor" href="#signals-and-processes" aria-label="Permalink to &quot;Signals and processes&quot;">​</a></h2><p>Ring-3 processes get signals through the syscall interface; the user test programs (<code>run signal_test</code>, <code>run fork_test</code>, <code>run exec_test</code>, <code>run pipe_test</code>, <code>run select_test</code>) demonstrate the full Unix-shaped process model: fork, exec, pipes, select, mmap.</p>',9)])])}const m=s(c,[["render",r]]);export{u as __pageData,m as default};
